   import collections

   # Convert all characters to lowercase and remove non-alphabetic characters
   value = re.sub(r'\W+', '', value.lower())

   # Group similar hospital types together
   grouped_hospital_types = collections.defaultdict(list)
   for hospital_type in value.split():
       grouped_hospital_types[hospital_type[:len(hospital_type)//2]].append(hospital_type)

   # Find the most frequent combinations of hospital type and ownership
   max_count = 0
   most_frequent_combinations = {}
   for key, values in grouped_hospital_types.items():
       count = collections.Counter(values).most_common(1)[0][1]
       if count > max_count:
           max_count = count
           most_frequent_combinations = {key: values}
       elif count == max_count:
           most_frequent_combinations[key] = values

   # Print the most frequent combinations of hospital type and ownership
   for combination in most_frequent_combinations.values():
       print(combination)
return value

